mapper.update:
UPDATE task SET status = #{status}, updated_at = #{now, typeHandler=com.agentcrossing.platform.infrastructure.persistence.mybatis.typehandler.InstantTypeHandler}
WHERE task_id = #{taskId}
AND status IN
#{state}

mapper.select:
SELECT * FROM task
WHERE trace_id = #{traceId}
ORDER BY created_at ASC, task_id ASC

SELECT * FROM task
WHERE trace_id = #{traceId} AND user_id = #{userId}
ORDER BY created_at ASC, task_id ASC

SELECT status, COUNT(*) AS task_count FROM task
WHERE trace_id = #{traceId} AND user_id = #{userId}
GROUP BY status

SELECT * FROM task
WHERE trace_id = #{traceId} AND user_id = #{userId}
ORDER BY updated_at DESC, created_at ASC, task_id ASC
LIMIT #{limit}

SELECT * FROM task
WHERE status = #{status}
ORDER BY created_at ASC, task_id ASC

SELECT * FROM task
WHERE status = #{status} AND user_id = #{userId}
ORDER BY created_at ASC, task_id ASC
